/**
 * Cinejoy webOS - Design System Tokens
 * Target: 10-Foot TV Experience (webOS 8.5.0 / 1920x1080)
 * Verified against live cinejoy.pk computed CSSOM and UI survey.
 */

:root {
  /* ==========================================================================
     Color Palette (Exact Survey Verified Values)
     ========================================================================== */
  --color-bg-base: #04120B;               /* Deep forest-obsidian canvas background */
  --color-bg-black: #000000;              /* Pitch black for player / OLED underlay */
  --color-accent-primary: #95FF50;        /* Electric neon lime accent (14.8:1 contrast) */
  --color-accent-secondary: #4F9E24;      /* Deep green supporting accent */
  --color-accent-glow: rgba(149, 255, 80, 0.65);

  /* Surfaces & Glassmorphism */
  --color-surface-glass: rgba(14, 14, 16, 0.45);
  --color-surface-glass-solid: rgba(14, 18, 16, 0.92);
  --color-surface-card: rgba(255, 255, 255, 0.05);
  --color-surface-hover: rgba(255, 255, 255, 0.10);
  --color-surface-active: rgba(255, 255, 255, 0.15);
  --color-surface-modal: rgba(20, 24, 22, 0.96);

  /* Borders */
  --color-border-subtle: rgba(255, 255, 255, 0.08);
  --color-border-card: rgba(255, 255, 255, 0.12);
  --color-border-hover: rgba(255, 255, 255, 0.25);

  /* Typography Colors */
  --color-text-primary: #FFFFFF;
  --color-text-secondary: rgba(255, 255, 255, 0.70);
  --color-text-muted: rgba(255, 255, 255, 0.40);
  --color-star: #FACC15;                  /* Bright gold star rating */
  --color-badge-blue: #38BDF8;

  /* ==========================================================================
     Typography Scale (10-Foot Television 1080p Hierarchy)
     ========================================================================== */
  --font-family-base: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-family-headings: Montserrat, Inter, sans-serif;

  --font-size-display: 56px;              /* Hero banner titles */
  --font-size-h1: 40px;                   /* Major view headings */
  --font-size-h2: 28px;                   /* Shelf section headers */
  --font-size-h3: 20px;                   /* Card / item titles */
  --font-size-body-large: 22px;           /* Hero & detail synopses */
  --font-size-body: 18px;                 /* Standard text & buttons */
  --font-size-caption: 14px;              /* Metadata pills & badges */

  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  --line-height-tight: 1.15;
  --line-height-normal: 1.4;
  --line-height-relaxed: 1.6;

  /* ==========================================================================
     10-Foot TV Canvas & Safe Area Standards
     ========================================================================== */
  --canvas-width: 1920px;
  --canvas-height: 1080px;

  /* 5% Title-Safe Margin (SMPTE RP 2046-1 / EBU R95) */
  --tv-safe-x: 96px;                      /* 5% horizontal margin */
  --tv-safe-y: 54px;                      /* 5% vertical margin */
  --tv-usable-width: 1728px;              /* 1920 - 192 */
  --tv-usable-height: 972px;              /* 1080 - 108 */

  /* ==========================================================================
     Card & Component Sizing
     ========================================================================== */
  --card-poster-width: 220px;
  --card-poster-height: 330px;            /* TMDB 2:3 aspect ratio */
  --card-episode-width: 320px;
  --card-episode-height: 180px;           /* 16:9 aspect ratio */
  --card-provider-size: 80px;
  --hero-banner-height: 600px;
  --header-height: 84px;

  /* Border Radii */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 9999px;

  /* Elevations & Shadows */
  --shadow-card: 0 12px 24px rgba(0, 0, 0, 0.45);
  --shadow-glass: 0 20px 50px rgba(0, 0, 0, 0.50);
  --shadow-glow: 0 0 28px rgba(149, 255, 80, 0.65);

  /* ==========================================================================
     Spatial Remote Focus Indicators
     ========================================================================== */
  --focus-border-color: #95FF50;
  --focus-border-width: 3px;
  --focus-outline: none;
  --focus-scale: 1.08;
  --focus-transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.2s ease, border-color 0.2s ease;
}

/**
 * Cinejoy webOS - 10-Foot TV Layout Engine
 * Target: webOS 8.5.0 Full HD (1920 x 1080)
 * Enforces strict 5% TV-Safe Area (96px horizontal, 54px vertical)
 * Zero scrollbars, 1080p locked canvas
 */

/* ==========================================================================
   Base Reset & TV Canvas Lock
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html, body {
  width: var(--canvas-width, 1920px);
  height: var(--canvas-height, 1080px);
  min-width: 1920px;
  min-height: 1080px;
  max-width: 1920px;
  max-height: 1080px;
  margin: 0;
  padding: 0;
  background-color: var(--color-bg-base);
  color: var(--color-text-primary);
  font-family: var(--font-family-base);
  font-size: var(--font-size-body);
  line-height: var(--line-height-normal);
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
  scrollbar-width: none;
  -ms-overflow-style: none;
  cursor: default;
}

body::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/* ==========================================================================
   Root Application Container
   ========================================================================== */
#app {
  position: relative;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background: radial-gradient(circle at 50% 0%, #0a2517 0%, var(--color-bg-base) 70%);
}

/* TV-Safe Zone Standard Wrapper */
.tv-safe-area {
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  padding-top: var(--tv-safe-y);
  padding-bottom: var(--tv-safe-y);
  width: 100%;
  height: 100%;
}

/* ==========================================================================
   Header Container (Fixed Glass Navigation Bar)
   ========================================================================== */
.app-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 1920px;
  height: var(--header-height);
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 100;
  pointer-events: auto;
  background: linear-gradient(180deg, rgba(4, 18, 11, 0.85) 0%, rgba(4, 18, 11, 0) 100%);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.app-header.header-hidden {
  opacity: 0;
  transform: translateY(-100%);
  pointer-events: none;
}

/* ==========================================================================
   Views Hierarchy & Router Container
   ========================================================================== */
.views-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
}

.view {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  display: none;
  opacity: 0;
  transform: scale(0.99);
  transition: opacity 0.28s cubic-bezier(0.2, 0, 0, 1), transform 0.28s cubic-bezier(0.2, 0, 0, 1);
}

.view.active {
  display: block;
  opacity: 1;
  transform: scale(1.0);
}

/* Scrollable View Content Pane */
.view-scroll-pane {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow-y: scroll;
  overflow-x: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-behavior: smooth;
  padding-top: var(--header-height);
  padding-bottom: 72px;
}

.view-scroll-pane::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/* ==========================================================================
   Grids & Content Shelves
   ========================================================================== */
/* Horizontal Content Shelf */
.content-shelf {
  position: relative;
  margin-top: 36px;
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  width: 100%;
}

.shelf-rail {
  display: flex;
  gap: 24px;
  overflow-x: hidden;
  overflow-y: visible;
  padding-top: 20px;
  padding-bottom: 24px;
  padding-left: 4px;
  padding-right: var(--tv-safe-x);
  scroll-behavior: smooth;
}

/* 6-Column Grid Layout for Movies, Series, and Search Results */
.content-grid-6col {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 28px 24px;
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  padding-top: 24px;
  padding-bottom: 64px;
  width: 100%;
}

/* Zero Scrollbar Enforcer */
.no-scrollbar {
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/**
 * Cinejoy webOS - UI Components Design System
 * 10-Foot Television Architecture (webOS 8.5.0)
 * Authentic recreation of cinejoy.pk styling & components
 */

/* ==========================================================================
   Brand Logo & Header Navigation Pill
   ========================================================================== */
.brand-container {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  text-decoration: none;
}

.brand-logomark {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.brand-logomark svg {
  width: 100%;
  height: 100%;
}

.brand-wordmark {
  font-family: var(--font-family-headings);
  font-size: 26px;
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.02em;
  color: var(--color-text-primary);
}

.brand-wordmark .accent {
  color: var(--color-accent-primary);
}

/* Floating Glass Header Pill */
.nav-glass-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  background-color: var(--color-surface-glass);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-pill);
  box-shadow: var(--shadow-glass);
}

.nav-pill-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 24px;
  border-radius: var(--radius-pill);
  color: var(--color-text-secondary);
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-medium);
  text-decoration: none;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
}

.nav-pill-item svg {
  width: 20px;
  height: 20px;
  stroke-width: 2.2;
}

.nav-pill-item.active {
  color: #04120B;
  background-color: var(--color-accent-primary);
  font-weight: var(--font-weight-bold);
  box-shadow: 0 0 16px var(--color-accent-glow);
}

.nav-pill-item.active svg {
  stroke: #04120B;
}

.nav-divider {
  width: 1px;
  height: 24px;
  background-color: var(--color-border-subtle);
  margin: 0 4px;
}

/* ==========================================================================
   Hero Banner (600px Height, 10-Foot Ergonomics)
   ========================================================================== */
.hero-banner {
  position: relative;
  width: 100%;
  height: var(--hero-banner-height);
  overflow: hidden;
  display: flex;
  align-items: flex-end;
  padding-bottom: 48px;
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
}

.hero-backdrop-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.hero-backdrop-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
}

.hero-gradient-overlay {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: 
    linear-gradient(180deg, rgba(4, 18, 11, 0.15) 0%, rgba(4, 18, 11, 0.5) 50%, var(--color-bg-base) 98%),
    linear-gradient(90deg, var(--color-bg-base) 0%, rgba(4, 18, 11, 0.85) 35%, rgba(4, 18, 11, 0.3) 70%, rgba(4, 18, 11, 0) 100%);
}

.hero-content {
  position: relative;
  z-index: 3;
  max-width: 960px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hero-logo-box {
  min-height: 80px;
  max-height: 130px;
  display: flex;
  align-items: flex-end;
}

.hero-clear-logo {
  max-height: 110px;
  max-width: 480px;
  object-fit: contain;
  object-position: left bottom;
  filter: drop-shadow(0 4px 16px rgba(0, 0, 0, 0.85));
}

.hero-title-fallback {
  font-family: var(--font-family-headings);
  font-size: var(--font-size-display);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
  color: var(--color-text-primary);
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.9);
}

.hero-meta-row {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: var(--font-size-caption);
  color: var(--color-text-secondary);
}

.badge-pill {
  padding: 4px 14px;
  border-radius: var(--radius-pill);
  background-color: var(--color-surface-card);
  border: 1px solid var(--color-border-card);
  font-weight: var(--font-weight-semibold);
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.badge-pill.rating {
  color: var(--color-star);
  border-color: rgba(250, 204, 21, 0.3);
}

.badge-pill.accent {
  color: var(--color-accent-primary);
  border-color: rgba(149, 255, 80, 0.4);
}

.hero-synopsis {
  font-size: var(--font-size-body-large);
  color: var(--color-text-secondary);
  line-height: 1.45;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  max-width: 820px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.85);
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 6px;
}

/* Action Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--font-family-base);
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-medium);
  border-radius: var(--radius-pill);
  cursor: pointer;
  border: 2px solid transparent;
  transition: all 0.2s ease;
  text-decoration: none;
}

.btn svg {
  width: 22px;
  height: 22px;
}

.btn-primary {
  height: 52px;
  padding: 0 32px;
  background-color: var(--color-accent-primary);
  color: #04120B;
  font-weight: var(--font-weight-bold);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.btn-secondary {
  height: 52px;
  padding: 0 26px;
  background-color: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--color-text-primary);
  border: 1px solid var(--color-border-card);
}

/* Split Action Button Group */
.split-action-group {
  display: inline-flex;
  align-items: center;
  height: 52px;
  border-radius: var(--radius-pill);
  background-color: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--color-border-card);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  overflow: hidden;
}

.split-action-btn {
  height: 100%;
  padding: 0 22px;
  background: transparent;
  border: none;
  color: var(--color-text-primary);
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-medium);
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.split-action-divider {
  width: 1px;
  height: 24px;
  background-color: rgba(255, 255, 255, 0.2);
}

/* ==========================================================================
   Content Shelves & Headers
   ========================================================================== */
.shelf-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 2px;
}

.shelf-title {
  font-family: var(--font-family-headings);
  font-size: var(--font-size-h2);
  font-weight: var(--font-weight-bold);
  color: var(--color-text-primary);
  letter-spacing: -0.01em;
}

.shelf-view-all {
  font-size: var(--font-size-caption);
  color: var(--color-text-muted);
  text-decoration: none;
  font-weight: var(--font-weight-medium);
}

/* ==========================================================================
   Content Cards (2:3 TMDB Aspect Ratio - 220px x 330px)
   Eliminates desktop hover reliance: Persistent title, year, rating
   ========================================================================== */
.card-poster {
  flex: 0 0 var(--card-poster-width);
  width: var(--card-poster-width);
  display: flex;
  flex-direction: column;
  cursor: pointer;
  text-decoration: none;
  position: relative;
  border-radius: var(--radius-md);
  outline: none;
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1);
}

.poster-media {
  width: var(--card-poster-width);
  height: var(--card-poster-height);
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  background: var(--color-surface-card);
  box-shadow: var(--shadow-card);
  border: 1px solid var(--color-border-card);
}

.poster-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  background-color: #0b1a11;
}

.poster-rating-badge {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(4, 18, 11, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-pill);
  padding: 3px 8px;
  font-size: 13px;
  font-weight: var(--font-weight-bold);
  color: var(--color-star);
  display: flex;
  align-items: center;
  gap: 4px;
}

.poster-rating-badge svg {
  width: 12px;
  height: 12px;
  fill: var(--color-star);
}

/* Persistent resting title and meta (zero mouse hover reliance) */
.poster-info {
  padding-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
}

.poster-title {
  font-size: 16px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.poster-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--color-text-secondary);
}

.poster-meta .dot {
  font-size: 10px;
  color: var(--color-text-muted);
}

/* ==========================================================================
   Episode Still Cards (16:9 Aspect Ratio - 320px x 180px)
   ========================================================================== */
.card-episode {
  flex: 0 0 var(--card-episode-width);
  width: var(--card-episode-width);
  display: flex;
  flex-direction: column;
  cursor: pointer;
  text-decoration: none;
  border-radius: var(--radius-md);
  outline: none;
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1);
}

.episode-media {
  width: var(--card-episode-width);
  height: var(--card-episode-height);
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  background: var(--color-surface-card);
  border: 1px solid var(--color-border-card);
  box-shadow: var(--shadow-card);
}

.episode-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  background-color: #0b1a11;
}

.episode-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: rgba(4, 18, 11, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-pill);
  padding: 3px 10px;
  font-size: 12px;
  font-weight: var(--font-weight-bold);
  color: #FFFFFF;
}

.episode-runtime {
  position: absolute;
  bottom: 10px;
  right: 10px;
  background: rgba(4, 18, 11, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-pill);
  padding: 3px 8px;
  font-size: 12px;
  font-weight: var(--font-weight-medium);
  color: var(--color-text-secondary);
}

.episode-info {
  padding-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.episode-title {
  font-size: 16px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.episode-overview {
  font-size: 13px;
  color: var(--color-text-muted);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  line-height: 1.35;
}

/* ==========================================================================
   Provider Tiles (Browse by Provider)
   ========================================================================== */
.card-provider {
  flex: 0 0 var(--card-provider-size);
  width: var(--card-provider-size);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  text-decoration: none;
  border-radius: var(--radius-lg);
  outline: none;
