/**
 * Cinejoy webOS - Spatial Remote Focus & Navigation System
 * Strict 10-Foot TV Focus Standard (#95FF50 14.8:1 High-Contrast Focus Ring)
 * Target: webOS 8.5.0 Remote Controls & D-Pad
 */

/* ==========================================================================
   Base Navigable Element Attributes & GPU Layer Promotion
   ========================================================================== */
[data-nav="true"] {
  outline: none;
  -webkit-tap-highlight-color: transparent;
  will-change: transform, box-shadow;
  transform: translateZ(0);
}

/* ==========================================================================
   Active Focused Element Standard (14.8:1 WCAG AAA High Contrast)
   ========================================================================== */
[data-nav="true"].focused,
[data-nav="true"]:focus-visible,
.focused,
.tv-focused {
  outline: none !important;
  border: 3px solid #95FF50 !important;
  box-shadow: 0 0 28px rgba(149, 255, 80, 0.65) !important;
  transform: scale(1.08) !important;
  z-index: 50 !important;
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.2s ease, border-color 0.2s ease !important;
}

/* ==========================================================================
   Component-Specific Focus Refinements
   ========================================================================== */

/* Header Navigation Pills */
.nav-pill-item[data-nav="true"].focused,
.nav-pill-item.focused {
  background-color: rgba(149, 255, 80, 0.25) !important;
  color: #FFFFFF !important;
  border-color: #95FF50 !important;
}

