/**
 * Cinejoy webOS - Application Bootstrap & View Router
 * 10-Foot Television User Interface Controller
 * Manages view switching (#home, #movies, #series, #search, #details, #player),
 * active nav indicators, and spatial focus coordination.
 */

(function (global) {
  'use strict';

  var CinejoyApp = {
    // Current Application State
    state: {
      currentView: 'home',
      previousView: null,
      searchQuery: '',
      activeDetailItem: null,
      focusedElement: null
    },

    // View Registry
    views: ['home', 'movies', 'series', 'search', 'details', 'player'],

    /**
     * Initialize application on DOM ready
     */
    init: function () {
      console.log('[CinejoyApp] Initializing 10-foot TV application shell...');
      this.bindEvents();
      this.initRouting();
      this.initKeyboard();
      this.setInitialFocus();
      console.log('[CinejoyApp] Application shell initialized successfully.');
    },

    /**
     * Bind UI event listeners (clicks, navigation changes)
     */
    bindEvents: function () {
      var self = this;

      // Header Navigation clicks
      var navItems = document.querySelectorAll('.nav-pill-item');
      navItems.forEach(function (item) {
        item.addEventListener('click', function (e) {
          e.preventDefault();
          var targetView = item.getAttribute('data-route');
          if (targetView) {
            self.switchView(targetView);
            self.setFocus(item);
          }
        });
      });

      // Quick-action and card clicks
      document.addEventListener('click', function (e) {
        var card = e.target.closest('.card-poster');
        if (card) {
          e.preventDefault();
          var title = card.getAttribute('data-title') || card.querySelector('.poster-title')?.textContent || 'Content Details';
          var year = card.getAttribute('data-year') || '2026';
          var rating = card.getAttribute('data-rating') || '8.5';
          var image = card.querySelector('img')?.getAttribute('src') || '';
          self.openDetails({
            title: title,
            year: year,
            rating: rating,
            image: image,
            type: card.getAttribute('data-type') || 'movie'
          });
          return;
        }

        // Hero Play Button
        var playBtn = e.target.closest('#hero-play-btn, #details-play-btn');
        if (playBtn) {
          e.preventDefault();
          self.switchView('player');
          return;
        }

        // Details Button
        var detailsBtn = e.target.closest('#hero-details-btn');
        if (detailsBtn) {
          e.preventDefault();
          self.openDetails({
            title: 'Dune: Part Two',
            year: '2024',
            rating: '8.6',
            type: 'movie'
          });
          return;
        }

        // Player Back / Exit
        var playerBack = e.target.closest('#player-back-btn');
        if (playerBack) {
          e.preventDefault();
          self.exitPlayer();
          return;
        }

        // Any navigable element clicked
        var navEl = e.target.closest('[data-nav="true"]');
        if (navEl) {
          self.setFocus(navEl);
        }
      });

      // Listen for hash changes if user or remote triggers URL change
      window.addEventListener('hashchange', function () {
        var hash = window.location.hash.replace('#', '') || 'home';
        if (self.views.indexOf(hash) !== -1 && hash !== self.state.currentView) {
          self.switchView(hash);
        }
      });

      // Listen for D-pad / Keyboard keys
      window.addEventListener('keydown', function (e) {
        self.handleKeyDown(e);
      });
    },

    /**
     * Initial Route Resolution
     */
    initRouting: function () {
      var initialHash = window.location.hash.replace('#', '') || 'home';
      if (this.views.indexOf(initialHash) === -1) {
        initialHash = 'home';
      }
      this.switchView(initialHash);
    },

    /**
     * Switch view between home, movies, series, search, details, player
     * @param {string} viewName - Target view name
     * @param {Object} [data] - Optional payload for view
     */
    switchView: function (viewName, data) {
      if (this.views.indexOf(viewName) === -1) {
        console.warn('[CinejoyApp] Unknown view: ' + viewName);
        return;
      }

      console.log('[CinejoyApp] Switching view: ' + this.state.currentView + ' -> ' + viewName);
      this.state.previousView = this.state.currentView;
      this.state.currentView = viewName;

      // Update URL hash
      if (window.location.hash !== '#' + viewName) {
        window.location.hash = '#' + viewName;
      }

      // Hide all views
      var allViews = document.querySelectorAll('.view');
      allViews.forEach(function (v) {
        v.classList.remove('active');
      });

      // Show target view
      var targetViewEl = document.getElementById('view-' + viewName);
      if (targetViewEl) {
        targetViewEl.classList.add('active');
        // Reset scroll position to top
        var scrollPane = targetViewEl.querySelector('.view-scroll-pane');
        if (scrollPane) {
          scrollPane.scrollTop = 0;
        }
      }

      // Header Visibility & Active Nav Item
      var header = document.querySelector('.app-header');
      if (header) {
        if (viewName === 'player') {
          header.classList.add('header-hidden');
        } else {
          header.classList.remove('header-hidden');
        }
      }

      // Update Header active indicator
      var navItems = document.querySelectorAll('.nav-pill-item');
      navItems.forEach(function (item) {
        if (item.getAttribute('data-route') === viewName) {
          item.classList.add('active');
        } else {
          item.classList.remove('active');
        }
      });

      // If opening player view, handle video playback element
      var videoEl = document.getElementById('main-video-player');
      if (viewName === 'player') {
        if (videoEl && videoEl.paused) {
          // Video element ready for playback
        }
      } else if (videoEl && !videoEl.paused) {
        videoEl.pause();
      }

      // Set focus to the first navigable element in the new view
      var self = this;
      setTimeout(function () {
        self.focusFirstElementInView(viewName);
      }, 50);
    },

    /**
     * Open Details View with specified item payload
     */
    openDetails: function (item) {
      this.state.activeDetailItem = item;
      if (item && item.title) {
        var titleEl = document.getElementById('details-title');
        if (titleEl) titleEl.textContent = item.title;
        var metaYearEl = document.getElementById('details-meta-year');
        if (metaYearEl && item.year) metaYearEl.textContent = item.year;
        var metaRatingEl = document.getElementById('details-meta-rating');
        if (metaRatingEl && item.rating) metaRatingEl.textContent = '★ ' + item.rating;
      }
      this.switchView('details', item);
    },

    /**
     * Exit player view back to previous screen
     */
    exitPlayer: function () {
      var returnView = this.state.previousView || 'home';
      if (returnView === 'player') returnView = 'home';
      this.switchView(returnView);
    },

    /**
     * Set focus on target element and apply high-contrast focus ring
     * @param {HTMLElement} element
     */
    setFocus: function (element) {
      if (!element) return;

      // Remove focus from previously focused element
      if (this.state.focusedElement && this.state.focusedElement !== element) {
        this.state.focusedElement.classList.remove('focused', 'tv-focused');
      }

      this.state.focusedElement = element;
      element.classList.add('focused', 'tv-focused');

      // Native focus if applicable
      if (typeof element.focus === 'function') {
        element.focus({ preventScroll: true });
      }

      // Ensure element is visible inside its scrollable parent
      element.scrollIntoView({
        behavior: 'smooth',
        block: 'nearest',
        inline: 'nearest'
      });
    },

    /**
     * Focus first navigable element in given view
     */
    focusFirstElementInView: function (viewName) {
      var viewEl = document.getElementById('view-' + viewName);
      if (!viewEl) return;

      // Prefer focused element in view, or first element marked data-nav="true"
      var firstNav = viewEl.querySelector('[data-nav="true"]');
      if (firstNav) {
        this.setFocus(firstNav);
      } else {
        // Fallback to active header pill
        var activeNavPill = document.querySelector('.nav-pill-item.active');
        if (activeNavPill) {
          this.setFocus(activeNavPill);
        }
      }
    },

    /**
     * Set initial focus on app launch
     */
    setInitialFocus: function () {
      var initialFocus = document.querySelector('.nav-pill-item.active') ||
                         document.querySelector('[data-nav="true"]');
      if (initialFocus) {
        this.setFocus(initialFocus);
      }
    },

    /**
     * Handle remote control and keyboard navigation
     */
    handleKeyDown: function (e) {
      var key = e.key;
      var keyCode = e.keyCode;

      // webOS Back Key (keycode 461), Escape (27), Backspace
      if (keyCode === 461 || key === 'Escape') {
        e.preventDefault();
        this.handleBackNavigation();
        return;
      }

      // Enter / OK key (keycode 13)
      if (key === 'Enter' || keyCode === 13) {
        if (this.state.focusedElement) {
          this.state.focusedElement.click();
        }
        return;
      }

      // Spatial Arrow keys
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].indexOf(key) !== -1) {
        this.navigateSpatial(key, e);
      }
    },

    /**
     * Back button hierarchical handler
     */
    handleBackNavigation: function () {
      if (this.state.currentView === 'player') {
        this.exitPlayer();
      } else if (this.state.currentView === 'details') {
        var returnView = this.state.previousView || 'home';
        this.switchView(returnView);
      } else if (this.state.currentView !== 'home') {
        this.switchView('home');
      } else {
        console.log('[CinejoyApp] Back pressed on home view. (webOS app exit threshold)');
      }
    },

    /**
     * Spatial 2D navigation algorithm between navigable items
     */
    navigateSpatial: function (direction, event) {
      var current = this.state.focusedElement;
      if (!current) {
        this.setInitialFocus();
        return;
      }

      var currentRect = current.getBoundingClientRect();
      var activeView = document.getElementById('view-' + this.state.currentView);
      var navCandidates = [];

      // Include header nav items if header is visible
      var header = document.querySelector('.app-header');
      if (header && !header.classList.contains('header-hidden')) {
        var headerNavs = header.querySelectorAll('[data-nav="true"]');
        for (var h = 0; h < headerNavs.length; h++) {
          navCandidates.push(headerNavs[h]);
        }
      }

      // Include view nav items
      if (activeView) {
        var viewNavs = activeView.querySelectorAll('[data-nav="true"]');
        for (var v = 0; v < viewNavs.length; v++) {
          navCandidates.push(viewNavs[v]);
        }
      }

      var bestCandidate = null;
      var minDistance = Infinity;

      for (var i = 0; i < navCandidates.length; i++) {
        var cand = navCandidates[i];
        if (cand === current) continue;

        var candRect = cand.getBoundingClientRect();
        if (candRect.width === 0 || candRect.height === 0) continue;

        var isDirectional = false;
        var primaryDiff = 0;
        var secondaryDiff = 0;

        var currentCenterX = currentRect.left + currentRect.width / 2;
        var currentCenterY = currentRect.top + currentRect.height / 2;
        var candCenterX = candRect.left + candRect.width / 2;
        var candCenterY = candRect.top + candRect.height / 2;

        if (direction === 'ArrowRight' && candRect.left >= currentRect.right - 10) {
          isDirectional = true;
          primaryDiff = candRect.left - currentRect.right;
          secondaryDiff = Math.abs(candCenterY - currentCenterY);
        } else if (direction === 'ArrowLeft' && candRect.right <= currentRect.left + 10) {
          isDirectional = true;
          primaryDiff = currentRect.left - candRect.right;
          secondaryDiff = Math.abs(candCenterY - currentCenterY);
        } else if (direction === 'ArrowDown' && candRect.top >= currentRect.bottom - 10) {
          isDirectional = true;
          primaryDiff = candRect.top - currentRect.bottom;
          secondaryDiff = Math.abs(candCenterX - currentCenterX);
        } else if (direction === 'ArrowUp' && candRect.bottom <= currentRect.top + 10) {
          isDirectional = true;
          primaryDiff = currentRect.top - candRect.bottom;
          secondaryDiff = Math.abs(candCenterX - currentCenterX);
        }

        if (isDirectional) {
          // Weight primary direction over secondary deviation
          var distance = primaryDiff * 1.0 + secondaryDiff * 2.2;
          if (distance < minDistance) {
            minDistance = distance;
            bestCandidate = cand;
          }
        }
      }

      if (bestCandidate) {
        event.preventDefault();
        this.setFocus(bestCandidate);
      }
    },

    /**
     * Virtual Keyboard handlers for On-Screen TV Search
     */
    initKeyboard: function () {
      var self = this;
      var keyboard = document.querySelector('.tv-keyboard-container');
      if (!keyboard) return;

      keyboard.addEventListener('click', function (e) {
        var keyBtn = e.target.closest('.key-btn');
        if (!keyBtn) return;

        var keyVal = keyBtn.getAttribute('data-key');
        var inputDisplay = document.getElementById('search-query-text');
        var placeholder = document.getElementById('search-query-placeholder');

        if (keyVal === 'BACKSPACE') {
          self.state.searchQuery = self.state.searchQuery.slice(0, -1);
        } else if (keyVal === 'CLEAR') {
          self.state.searchQuery = '';
        } else if (keyVal === 'SPACE') {
          self.state.searchQuery += ' ';
        } else if (keyVal) {
          self.state.searchQuery += keyVal;
        }

        if (inputDisplay) {
          inputDisplay.textContent = self.state.searchQuery;
        }
        if (placeholder) {
          placeholder.style.display = self.state.searchQuery ? 'none' : 'inline';
        }

        // Live filter search results grid
        self.updateSearchResults(self.state.searchQuery);
      });
    },

    /**
     * Update search results based on query
     */
    updateSearchResults: function (query) {
      var countEl = document.getElementById('search-results-count');
      var gridEl = document.getElementById('search-results-grid');
      if (!gridEl) return;

      var items = gridEl.querySelectorAll('.card-poster');
      var matched = 0;
      var lowerQuery = (query || '').toLowerCase().trim();

      items.forEach(function (item) {
        var title = (item.getAttribute('data-title') || '').toLowerCase();
        if (!lowerQuery || title.indexOf(lowerQuery) !== -1) {
          item.style.display = 'flex';
          matched++;
        } else {
          item.style.display = 'none';
        }
      });

      if (countEl) {
        countEl.textContent = lowerQuery ? '(' + matched + ' matches)' : '';
      }
    }
  };

  // Expose globally and support Node.js module export
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = CinejoyApp;
  }
  if (typeof window !== 'undefined') {
    window.CinejoyApp = CinejoyApp;
    document.addEventListener('DOMContentLoaded', function () {
      CinejoyApp.init();
    });
  }
  global.CinejoyApp = CinejoyApp;

})(typeof window !== 'undefined' ? window : this);

